cfg = maintenance_context();
load_system('tractor_mu'); rt=sfroot; e=rt.find('-isa','Stateflow.EMChart'); for k=1:numel(e), if contains(e(k).Path,'MATLAB Function4')||contains(e(k).Path,'MATLAB Function5'), fprintf('EM %s\n',e(k).Path); d=e(k).find('-isa','Stateflow.Data'); for i=1:numel(d), fprintf(' data %s %s %s\n',d(i).Name,d(i).Scope,d(i).Props.Array.Size); end; end, end; c=rt.find('-isa','Stateflow.Chart','Name','launch_state'); fprintf('chart sample=%s decomp=%s\n',c.SampleTime,c.Decomposition); s=c.find('-isa','Stateflow.State'); for i=1:numel(s), fprintf('state %s decomp=%s order=%d pos=%s\n',s(i).Name,s(i).Decomposition,s(i).ExecutionOrder,mat2str(s(i).Position)); end; close_system('tractor_mu',0); exit;
